(globalThis.CATALOGUE_RECORD_CHUNKS??=Object.create(null))[492]={"source_order":492,"notes":["The left-margin curved stroke near y≈1800–2000 could be a deliberate pencil mark or accidental graphite. No text is legible in it.","The faint ghost text is read as show-through rather than erased writing on this side, because its layout mirrors the recto. Very faint erasures beneath it cannot be fully excluded.","The faint text visible across the ruled lines is show-through from the recto, fol. 246. Its mirrored layout matches the adjacent recto's entries and right-hand shelfmark column. It is not transcribed as target-page content.","No facing-page fragments are present. The left edge shows the stacked page edges of the volume. Sewing thread is visible at the right gutter edge.","The page is blank of catalogue content except for the folio number '246b'. This finding comes from reviewing the overview and all six native tiles, covering the top, middle, bottom, both margins and the interlinear spaces.","The faint ghost writing across the ruled lines is show-through from the recto, fol. 246 (source order 491). Its mirrored layout matches the recto entries and the recto's shelfmark column. It is not transcribed as target-page content.","There is a short curved dark graphite stroke in the left part of the writing area at about [560,1800,60,200]. It is not legible text and is not attached to any entry.","There is a faint grey graphite smudge in the lower left area at about [810,4000,200,260]. It is not legible.","There are small dark specks, apparently ink spots or debris, near the right centre at about [2320,2970,50,80]. Other isolated specks are scattered across the page.","The stacked page edges of the volume are visible at the left. Sewing thread is visible at the right gutter edge. No facing-page fragments are present.","Faint mirrored ghost writing runs across the ruled lines. Its layout corresponds to the recto, fol. 246: an indented entry column and a right-hand shelfmark/date column, which appear on this verso as left-side fragments. It is treated as show-through. Very faint erasure on this side cannot be wholly excluded from the images."],"records":[{"id":"css-prod-0492-r001","local_id":"r001","source_order":492,"folio":"246b","folio_label":"fol. 246b","sequence":1,"page_id":"1baad97a-ed96-4598-af86-28d78071cf35","kind":"other","record_type":"non_catalogue_text","source_model_record_type":"non_catalogue_text","subtype":"folio_number","shelfmark":"","titleLiteral":"","titleNormalized":"","displayTitle":"Catalogue text","authorOrSource":"","source":"","subject":"","subjectGroup":"","date":"","extent":"","lines":"","script":"","incipit":"","transcription":"246b","annotations":["Pencil folio number in the top left corner of the page, at about [425,325,145,150].","The 'b' is written raised after '246', like a superscript."],"uncertainties":["Faint mirrored ghost writing runs across the ruled lines. Its layout corresponds to the recto, fol. 246: an indented entry column and a right-hand shelfmark/date column, which appear on this verso as left-side fragments. It is treated as show-through. Very faint erasure on this side cannot be wholly excluded from the images."],"focused_readings":[],"reviewNotes":[],"editorialNotes":[],"relationships":[],"editorial_context":[],"block_ids":["b001"],"locations":[{"block_id":"b001","bbox":[425,325,145,150]}],"isCancelled":false,"needsReview":true,"human_verified":false,"verification_status":"machine_reviewed","change_audit":[],"sourceCitationURL":"https://iiif.bodleian.ox.ac.uk/iiif/canvas/1baad97a-ed96-4598-af86-28d78071cf35.json","auditPath":"audit/pages/0492.json","attachedNotes":[],"resolvedRelationships":[],"attachedRecords":[]}]};
